// app/api/admin/promotions/route.ts — Admin Control Plane Promotions & Coupons Management API
import { NextResponse } from "next/server";
import { requireAdminInvisibility } from "@/app/lib/auth";
import { PromotionService } from "@/src/services/promotion.service";

export async function GET(request: Request) {
  const auth = await requireAdminInvisibility(request);
  if (auth.errorResponse) return auth.errorResponse;

  try {
    const url = new URL(request.url);
    const activeOnly = url.searchParams.get("activeOnly") === "true";

    const promotions = await PromotionService.listPromotions({ activeOnly });

    return NextResponse.json({
      success: true,
      count: promotions.length,
      promotions,
    });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err?.message || "Failed to load promotions" },
      { status: 500 }
    );
  }
}

export async function POST(request: Request) {
  const auth = await requireAdminInvisibility(request);
  if (auth.errorResponse) return auth.errorResponse;

  try {
    const body = await request.json();
    const promotion = await PromotionService.createPromotion(body);

    return NextResponse.json(
      {
        success: true,
        promotion,
      },
      { status: 201 }
    );
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err?.message || "Failed to create promotion" },
      { status: 400 }
    );
  }
}

export async function DELETE(request: Request) {
  const auth = await requireAdminInvisibility(request);
  if (auth.errorResponse) return auth.errorResponse;

  try {
    const url = new URL(request.url);
    const idParam = url.searchParams.get("id");
    if (!idParam) {
      return NextResponse.json({ error: "id parameter is required" }, { status: 400 });
    }

    const id = parseInt(idParam, 10);
    const deleted = await PromotionService.deletePromotion(id);

    return NextResponse.json({
      success: true,
      deleted,
    });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err?.message || "Failed to delete promotion" },
      { status: 500 }
    );
  }
}

