export interface SupplierOfferItem {
  id: string;
  supplier_id: string;
  supplier?: {
    id: string;
    name: string;
    email?: string;
    store_name?: string;
  };
  name: string;
  category: string;
  description?: string;
  account_format?: string;
  suggested_buying_price: number;
  asking_price?: number;
