  counter_note?: string | null;
  stock_units?: number;
  notes?: string;
  status: "PENDING" | "APPROVED" | "REJECTED" | "COUNTERED" | string;
  admin_notes?: string;
  created_at: string;
}

export function AdminOffersView() {
  const toast = useToast();
  const [offers, setOffers] = useState<SupplierOfferItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");

  // Counter Modal
  const [isCounterModalOpen, setIsCounterModalOpen] = useState(false);
  const [selectedOffer, setSelectedOffer] = useState<SupplierOfferItem | null>(null);
  const [counterPrice, setCounterPrice] = useState("");
  const [counterNotes, setCounterNotes] = useState("");
  const [isActionLoading, setIsActionLoading] = useState(false);

  const fetchOffers = useCallback(async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const res = await fetch("/api/admin/proposals", {
        cache: "no-store",
        credentials: "include",
      });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }
      const data = await res.json();
      if (!data.success && data.error) {
        throw new Error(data.message || data.error);
      }
      setOffers(data.proposals || data.data || []);
    } catch (err: any) {
      console.error("[AdminOffersView] Fetch error:", err);
      setError(err?.message || "Failed to load supplier offers.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchOffers();
  }, [fetchOffers]);

  const handleReviewDecision = async (
    offerId: string,
    decision: "APPROVE" | "REJECT" | "COUNTER",
    counterData?: { counterPrice?: number; counterNote?: string }
  ) => {
    setIsActionLoading(true);
    try {
      const res = await fetch("/api/admin/proposals/review", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          proposalId: offerId,
          decision,
          counterPrice: counterData?.counterPrice,
          notes: counterData?.counterNote,
        }),
      });
      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || "Failed to submit review decision");
      }
      toast.success(
        decision === "APPROVE"
          ? "Offer approved! Catalog item generated."
          : decision === "REJECT"
          ? "Offer rejected."
          : "Counter-offer sent to supplier."
      );
      setIsCounterModalOpen(false);
      setSelectedOffer(null);
      fetchOffers(true);
    } catch (err: any) {
      toast.error(err.message || "Failed to process review");
    } finally {
      setIsActionLoading(false);
    }
  };

  const filteredOffers = useMemo(() => {
    return offers.filter((item) => {
      if (statusFilter !== "ALL" && (item.status || "").toUpperCase() !== statusFilter) {
        return false;
      }
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matchesName = item.name.toLowerCase().includes(q);
        const matchesCat = (item.category || "").toLowerCase().includes(q);
        const matchesSupplier =
          (item.supplier?.name || "").toLowerCase().includes(q) ||
          (item.supplier?.store_name || "").toLowerCase().includes(q);
        if (!matchesName && !matchesCat && !matchesSupplier) return false;
      }
      return true;
    });
  }, [offers, statusFilter, searchQuery]);

  return (
    <div className="space-y-6 w-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-5 rounded-2xl bg-card border border-border">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl sm:text-2xl font-semibold text-foreground font-sans">
              Supplier offers
            </h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-mono bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20 font-medium">
              Proposals
            </span>
          </div>
          <p className="text-sm text-muted-foreground mt-0.5">
            Review new products and pricing proposed by verified suppliers.
          </p>
        </div>

        <button
          onClick={() => fetchOffers(true)}
          disabled={refreshing || loading}
          className="px-3 py-2 rounded-xl bg-secondary hover:bg-secondary/80 border border-border text-secondary-foreground hover:text-foreground text-xs font-mono transition-colors flex items-center gap-1.5 cursor-pointer disabled:opacity-50 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${refreshing ? "animate-spin text-amber-500" : ""}`} />
          <span>Sync</span>
        </button>
      </div>

      {/* Filter Toolbar */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3.5 rounded-xl bg-card border border-border">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by product, category, or supplier..."
            className="w-full pl-9 pr-4 py-1.5 text-xs rounded-lg bg-muted border border-border text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-emerald-500"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1 text-xs text-muted-foreground font-mono">
            <Filter className="w-3.5 h-3.5" />
            <span>Status:</span>
          </div>
