export function AdminPromotionsView() {
  const toast = useToast();
  const [promotions, setPromotions] = useState<PromotionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [archivingId, setArchivingId] = useState<number | null>(null);

  const fetchPromotions = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/promotions", { cache: "no-store", credentials: "include" });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || `HTTP ${res.status}`);
      setPromotions(data.promotions || []);
    } catch (err: any) {
      setError(err?.message || "Failed to load promotions.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPromotions();
  }, [fetchPromotions]);

  const handleArchive = async (promo: PromotionItem) => {
    if (!window.confirm(`Archive promotion ${promo.code}? It can no longer be redeemed.`)) return;
    setArchivingId(promo.id);
    try {
      const res = await fetch(`/api/admin/promotions/${promo.id}/archive`, {
        method: "POST",
        credentials: "include",
      });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || "Failed to archive promotion");
      toast.success(`Promotion ${promo.code} archived.`);
      setPromotions((prev) => prev.filter((p) => p.id !== promo.id));
    } catch (err: any) {
      toast.error(err.message || "Failed to archive promotion");
    } finally {
      setArchivingId(null);
    }
  };

  return (
    <div className="space-y-6 w-full">
      <div className="flex items-center justify-between gap-4 p-5 rounded-2xl bg-card border border-border">
        <div>
          <h1 className="text-xl sm:text-2xl font-semibold text-foreground font-sans">Promotions</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Manage discount codes. Archive a promotion to retire it while keeping its history.
          </p>
        </div>
        <button
          onClick={fetchPromotions}
          disabled={loading}
          className="px-3 py-2 rounded-xl bg-secondary hover:bg-secondary/80 border border-border text-xs font-mono flex items-center gap-1.5 cursor-pointer disabled:opacity-50"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
          <span>Sync</span>
        </button>
      </div>

      {error && (
        <div className="p-3 rounded-xl border border-red-500/20 bg-red-500/10 text-sm text-red-600">{error}</div>
      )}

      <div className="rounded-2xl bg-card border border-border overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-muted-foreground border-b border-border">
              <th className="p-3">Code</th>
              <th className="p-3">Title</th>
              <th className="p-3">Discount</th>
              <th className="p-3">Used</th>
              <th className="p-3">Status</th>
              <th className="p-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading && promotions.length === 0 ? (
              <tr>
                <td colSpan={6} className="p-6 text-center text-muted-foreground">
                  <Loader2 className="w-4 h-4 animate-spin inline" />
                </td>
              </tr>
            ) : promotions.length === 0 ? (
              <tr>
                <td colSpan={6} className="p-6 text-center text-muted-foreground">
                  <Ticket className="w-4 h-4 inline mr-1" /> No promotions.
                </td>
              </tr>
            ) : (
              promotions.map((p) => (
                <tr key={p.id} className="border-b border-border last:border-0">
                  <td className="p-3 font-mono">{p.code}</td>
                  <td className="p-3">{p.title}</td>
                  <td className="p-3">
                    {p.discount_type === "PERCENTAGE" ? `${p.discount_value}%` : `₱${p.discount_value.toFixed(2)}`}
                  </td>
                  <td className="p-3">
                    {p.used_count}
                    {p.usage_limit ? ` / ${p.usage_limit}` : ""}
                  </td>
                  <td className="p-3">{p.is_active ? "Active" : "Inactive"}</td>
                  <td className="p-3 text-right">
                    <button
                      onClick={() => handleArchive(p)}
                      disabled={archivingId === p.id}
                      className="px-2.5 py-1.5 rounded-lg bg-secondary hover:bg-secondary/80 border border-border text-xs font-mono inline-flex items-center gap-1.5 cursor-pointer disabled:opacity-50"
                    >
                      {archivingId === p.id ? (
                        <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      ) : (
                        <Archive className="w-3.5 h-3.5" />
                      )}
                      <span>Archive</span>
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { AdminPromotionsView } from "@/components/admin/AdminPromotionsView";

export default function AdminPromotionsPage() {
  return <AdminPromotionsView />;
}

