"use client";

import React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  Key,
  Boxes,
  ShoppingBag,
  Users,
  Settings,
  ShieldCheck,
  LogOut,
  Activity,
  Layers,
  FileText,
  UserCheck,
  Tag,
  CreditCard,
  Archive,
  Server,
} from "lucide-react";

export function AdminSidebar() {
  const pathname = usePathname();

  const navSections = [
    {
      title: "Overview",
      items: [
        {
          href: "/admin",
          label: "Overview",
          icon: LayoutDashboard,
          isActive: pathname === "/admin" || pathname === "/admin/",
        },
      ],
    },
    {
      title: "Commerce",
      items: [
        {
          href: "/admin/catalog",
          label: "Products",
          icon: Boxes,
          isActive: pathname.startsWith("/admin/catalog"),
        },
        {
          href: "/admin/inventory",
          label: "Inventory",
          icon: Key,
          isActive: pathname.startsWith("/admin/inventory"),
        },
        {
          href: "/admin/offers",
          label: "Offers",
          icon: Tag,
          isActive: pathname.startsWith("/admin/offers"),
        },
        {
          href: "/admin/orders",
          label: "Orders",
          icon: ShoppingBag,
          isActive: pathname.startsWith("/admin/orders"),
        },
      ],
    },
    {
      title: "Partners",
      items: [
        {
          href: "/admin/resellers",
          label: "Resellers",
          icon: Layers,
          isActive: pathname.startsWith("/admin/resellers"),
        },
        {
          href: "/admin/suppliers",
          label: "Suppliers",
          icon: Users,
          isActive: pathname === "/admin/suppliers" || (pathname.startsWith("/admin/suppliers") && !pathname.startsWith("/admin/upstream-suppliers")),
        },
        {
          href: "/admin/upstream-suppliers",
          label: "Dropship APIs",
          icon: Server,
          isActive: pathname.startsWith("/admin/upstream-suppliers"),
        },
        {
          href: "/admin/sourcing",
          label: "Product requests",
          icon: FileText,
          isActive: pathname.startsWith("/admin/sourcing"),
        },
      ],
    },
    {
      title: "Operations",
      items: [
        {
          href: "/admin/p2p-watchdog",
          label: "Payment monitoring",
          icon: Activity,
          isActive: pathname.startsWith("/admin/p2p-watchdog"),
        },
        {
          href: "/admin/payouts",
          label: "Payouts",
          icon: ShieldCheck,
          isActive: pathname.startsWith("/admin/payouts"),
        },
      ],
    },
    {
      title: "Administration",
      items: [
        {
          href: "/admin/staff",
          label: "Staff",
          icon: UserCheck,
          isActive: pathname.startsWith("/admin/staff"),
        },
        {
          href: "/admin/settings",
          label: "Settings",
          icon: Settings,
          isActive: pathname === "/admin/settings",
        },
        {
          href: "/admin/settings/payments",
          label: "Payment methods",
          icon: CreditCard,
          isActive: pathname === "/admin/settings/payments" || pathname.startsWith("/admin/settings/payments/"),
        },
        {
          href: "/admin/settings/purchases",
          label: "Purchase data",
          icon: Archive,
          isActive: pathname === "/admin/settings/purchases" || pathname.startsWith("/admin/settings/purchases/"),
        },
      ],
    },
  ];

  return (
    <aside className="hidden md:flex md:w-60 border-r border-border dark:border-white/[0.08] bg-card dark:bg-[#0b0c0e] flex-col justify-between p-3.5 flex-shrink-0 min-h-screen font-sans">
      <div className="overflow-y-auto no-bar">
        {/* Header Brand */}
        <div className="flex items-center space-x-2.5 px-2 py-2 mb-3 border-b border-border dark:border-white/[0.06]">
          <div className="w-7 h-7 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-mono font-bold text-xs">
            X
          </div>
          <div className="min-w-0">
            <div className="font-mono font-bold text-xs leading-none text-foreground tracking-wider uppercase">
              XNIGHT
            </div>
            <div className="text-[10px] font-mono text-muted-foreground dark:text-zinc-500 mt-0.5 flex items-center gap-1.5">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
              <span>Admin Console</span>
            </div>
          </div>
        </div>

        {/* Grouped Navigation */}
        <nav className="flex flex-col gap-2.5 pb-2">
          {navSections.map((section) => (
            <div key={section.title} className="flex flex-col gap-0.5">
              <div className="text-[10px] font-mono text-muted-foreground dark:text-zinc-500 uppercase tracking-wider px-2.5 py-1">
                {section.title}
              </div>
              {section.items.map((item) => {
                const Icon = item.icon;
                const active = item.isActive;
                return (
                  <Link
                    key={item.href}
                    href={item.href}
                    prefetch={true}
                    className={`flex items-center space-x-2.5 px-2.5 py-1.5 rounded-lg text-xs font-medium tracking-normal transition-colors whitespace-nowrap group ${
                      active
                        ? "bg-accent/80 dark:bg-white/[0.08] text-accent-foreground dark:text-white border border-border/80 dark:border-white/[0.06] font-semibold"
                        : "text-muted-foreground hover:text-foreground hover:bg-muted/60 dark:text-zinc-400 dark:hover:text-zinc-200 dark:hover:bg-white/[0.03]"
                    }`}
                  >
                    <Icon
                      className={`w-4 h-4 flex-shrink-0 transition-colors ${
                        active
                          ? "text-emerald-600 dark:text-emerald-400"
                          : "text-muted-foreground group-hover:text-foreground dark:text-zinc-400 dark:group-hover:text-zinc-200"
                      }`}
                    />
                    <span>{item.label}</span>
                  </Link>
                );
              })}
            </div>
          ))}
        </nav>
      </div>

      {/* Footer Exit Action */}
      <div className="pt-3 border-t border-border dark:border-white/[0.06] mt-4 md:mt-0">
        <form action="/api/auth/logout" method="POST">
          <button
            type="submit"
            className="w-full flex items-center space-x-2 px-2.5 py-1.5 rounded-lg text-xs font-medium text-muted-foreground hover:text-rose-500 hover:bg-rose-500/10 dark:text-zinc-400 dark:hover:text-rose-400 transition-colors cursor-pointer"
          >
            <LogOut className="w-3.5 h-3.5 flex-shrink-0" />
            <span>Sign Out</span>
          </button>
        </form>
      </div>
    </aside>
  );
}

export default AdminSidebar;
